(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*7;
  const sx = x + wx, sy = y + wy;
  const src = [
    [240+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [240+Math.sin(t*0.25)*180*Math.cos(t*0.1), 120+Math.cos(t*0.25)*120*Math.sin(t*0.1), 0.045, 3.0],
    [200+Math.cos(t*0.7+2)*60, 100+Math.sin(t*0.5+4)*40, 0.15, 1.3],
    [300+Math.sin(t*0.45+1)*70, 150+Math.cos(t*0.65+3)*50, 0.13, 1.4]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    wS += Math.sin(d*f*1.3 - t*sp*0.8 + 2.0) * 0.5;
  }
  const n = src.length, act = aS/n, inh = iS/n, wav = wS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.07-ang*2-t*2.0))*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.25-t*2.5)*0.15;
  const r1 = act - inh*0.7 + bg*0.3 + spiral, r2 = wav*0.6 - act*0.3 + inh*0.5;
  const reaction = Math.tanh(r1*2.2 + r2*0.8), secondary = Math.tanh(r2*1.8 - r1*0.4);
  const blend = reaction*0.6 + cell*0.2 + micro + secondary*0.2, v = blend*0.5+0.5;
  const pal = [[6,12,52],[12,45,85],[18,85,115],[25,140,135],[80,175,140],[180,195,100],[220,175,60],[215,120,55],[190,70,65],[130,35,65],[65,18,55],[6,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(secondary)*0.1;
  const edge = Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow = Math.max(0, 1-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
